import {type EncodableObject, encode, type SetSynchronization} from '@sanity/descriptors'
import type {SchemaTypeDefinition} from '@sanity/types'
import {convertDescriptorValidationToManifest} from './manifestValidation'
import type {
  EncodedSchemaSummary,
  HoistedEntry,
  HoistedMarker,
  InlineOrHoisted,
  SchemaSummary,
  SchemaSummaryChanges,
  TypeDef,
} from './types'

type DefinitionFormat = 'createSchema' | 'plain' | 'manifest'
type SchemaFormat = Exclude<DefinitionFormat, 'manifest'>
type SchemaDefinition = {name: string; types: SchemaTypeDefinition[]}
type ManifestTypeDefinition = {
  name: string
  type: string
  [key: string]: unknown
}
type ConvertedTypeDefinition = SchemaTypeDefinition | ManifestTypeDefinition
type ManifestDefinition = {
  name: string
  types: ManifestTypeDefinition[]
}
type ConvertedDefinition = SchemaDefinition | ManifestDefinition

export type {
  EncodedSchemaSummary,
  HoistedEntry,
  HoistedMarker,
  InlineOrHoisted,
  LexiconResponse,
  SchemaSummary,
  SchemaSummaryChanges,
  TypeDef,
} from './types'

/**
 * Takes the output from the `/schemas` endpoint and turns it into a schema definition.
 *
 * There's three formats:
 * - `createSchema` produces something which can be put _directly_ into `createSchema`.
 *   This means that it creates some dummy fields (e.g. `preview` selector for GDR/CDR).
 * - `plain` is very close.
 * - `manifest` serializes validation using the Sanity manifest rule format.
 */
export function convertToDefinition(
  input: SchemaSummary,
  opts: {format: 'manifest'},
): ManifestDefinition
export function convertToDefinition(
  input: SchemaSummary,
  opts?: {format?: 'createSchema' | 'plain'},
): SchemaDefinition
export function convertToDefinition(
  input: SchemaSummary,
  opts: {format?: DefinitionFormat} = {},
): ConvertedDefinition {
  const format = opts.format || 'plain'

  return format === 'manifest'
    ? convertManifestDefinition(input)
    : convertSchemaDefinition(input, format)
}

/** Converts an encoded schema set into the decoded summary used by the descriptor API. */
export function schemaSummaryFromSetSynchronization(
  synchronization: SetSynchronization<string>,
): SchemaSummary {
  const summary: SchemaSummary = {
    types: {},
    hoisted: {},
    registries: Object.keys(synchronization.setValues),
  }
  for (const value of Object.values(synchronization.objectValues)) {
    if (value.type === 'sanity.schema.namedType' && typeof value['name'] === 'string') {
      summary.types[value['name']] = value['typeDef'] as TypeDef
    } else if (value.type === 'sanity.schema.hoisted' && typeof value['key'] === 'string') {
      summary.hoisted[value['key']] = value['value'] as HoistedEntry
    }
  }
  return summary
}

/**
 * Applies explicitly changed fields and deleted types from a regenerated summary while retaining
 * every untouched descriptor from the original summary.
 */
export function mergeSchemaSummary(
  original: SchemaSummary,
  regenerated: SchemaSummary,
  changes: SchemaSummaryChanges,
): SchemaSummary {
  const deletedTypes = new Set(changes.deletedTypes)
  const hoisted = {...original.hoisted}
  const importedKeys = new Map<string, string>()
  const allocatedHoistKeys = new Set(Object.keys(hoisted))

  function importGeneratedHoists(value: unknown): unknown {
    const reachable = new Set<string>()

    function collect(candidate: unknown): void {
      if (Array.isArray(candidate)) {
        candidate.forEach(collect)
        return
      }
      if (candidate === null || typeof candidate !== 'object') return
      if (isHoistedMarker(candidate)) {
        if (reachable.has(candidate.key)) return
        const entry = regenerated.hoisted[candidate.key]
        if (!entry) throw new Error(`Unknown hoisted key: ${candidate.key}`)
        reachable.add(candidate.key)
        collect(entry)
        return
      }
      Object.values(candidate).forEach(collect)
    }

    collect(value)
    for (const sourceKey of reachable) {
      if (importedKeys.has(sourceKey)) continue
      let targetKey = sourceKey
      for (let suffix = 1; allocatedHoistKeys.has(targetKey); suffix++) {
        targetKey = `${sourceKey}.replacement${suffix}`
      }
      importedKeys.set(sourceKey, targetKey)
      allocatedHoistKeys.add(targetKey)
    }

    function rewrite(candidate: unknown): unknown {
      if (Array.isArray(candidate)) return candidate.map(rewrite)
      if (candidate === null || typeof candidate !== 'object') return candidate
      if (isHoistedMarker(candidate)) {
        return {...candidate, key: importedKeys.get(candidate.key) ?? candidate.key}
      }
      return Object.fromEntries(
        Object.entries(candidate).map(([key, nested]) => [key, rewrite(nested)]),
      )
    }

    for (const sourceKey of reachable) {
      const targetKey = importedKeys.get(sourceKey)!
      if (!(targetKey in hoisted)) {
        hoisted[targetKey] = rewrite(regenerated.hoisted[sourceKey]) as HoistedEntry
      }
    }
    return rewrite(value)
  }

  const types = Object.fromEntries(
    Object.entries(original.types).flatMap(([typeName, originalType]) => {
      if (deletedTypes.has(typeName)) return []
      const changedFieldNames = changes.changedFields?.[typeName]
      if (!changedFieldNames?.length) return [[typeName, originalType]]

      const regeneratedType = regenerated.types[typeName]
      if (!regeneratedType) throw new Error(`Regenerated schema is missing type: ${typeName}`)
      const fields = [...(originalType.fields ?? [])]
      const currentFieldNames = fields.map((field) => getFieldName(field, original.hoisted))
      for (const fieldName of changedFieldNames) {
        const originalIndex = currentFieldNames.indexOf(fieldName)
        const regeneratedField = regeneratedType.fields?.find(
          (field) => getFieldName(field, regenerated.hoisted) === fieldName,
        )
        if (!regeneratedField) {
          if (originalIndex >= 0) {
            fields.splice(originalIndex, 1)
            currentFieldNames.splice(originalIndex, 1)
          }
          continue
        }

        const replacement = importGeneratedHoists(regeneratedField) as InlineOrHoisted
        if (originalIndex >= 0) fields[originalIndex] = replacement
        else {
          fields.push(replacement)
          currentFieldNames.push(fieldName)
        }
      }
      return [[typeName, {...originalType, fields}]]
    }),
  )

  return {types, hoisted, registries: original.registries}
}

/** Encodes a complete schema summary into the descriptor graph accepted by the upload API. */
export function encodeSchemaSummary(summary: SchemaSummary): EncodedSchemaSummary {
  const descriptors: EncodedSchemaSummary['descriptors'] = {}
  const add = (type: string, value: EncodableObject): string => {
    const encoded = encode(type, value)
    descriptors[encoded.id] = encoded
    return encoded.id
  }
  const keys = [
    ...Object.entries(summary.types).map(([name, typeDef]) =>
      add('sanity.schema.namedType', {name, typeDef} as EncodableObject),
    ),
    ...Object.entries(summary.hoisted).map(([key, value]) =>
      add('sanity.schema.hoisted', {key, value} as EncodableObject),
    ),
    ...summary.registries,
  ].sort()
  const registry = encode('sanity.schema.registry', {keys})
  descriptors[registry.id] = registry
  return {descriptorId: registry.id, descriptors}
}

function getFieldName(
  field: InlineOrHoisted,
  hoisted: SchemaSummary['hoisted'],
): string | undefined {
  if (!isHoistedMarker(field)) return field.name
  const entry = hoisted[field.key]
  if (!entry) throw new Error(`Unknown hoisted key: ${field.key}`)
  return entry.name
}

function convertSchemaDefinition(input: SchemaSummary, format: SchemaFormat): SchemaDefinition {
  const convertTypeDef = createTypeDefConverter(input, format)
  const types = Object.entries(input.types).map(([name, typeDef]) => convertTypeDef(name, typeDef))

  return {name: 'schema', types}
}

// Keep the schema and manifest wrappers separate so convertToDefinition's
// overloads retain narrow return types without pushing casts into callers.
function convertManifestDefinition(input: SchemaSummary): ManifestDefinition {
  const convertTypeDef = createTypeDefConverter(input, 'manifest')
  const types = Object.entries(input.types).map(([name, typeDef]) => convertTypeDef(name, typeDef))

  return {name: 'schema', types}
}

function createTypeDefConverter(
  input: SchemaSummary,
  format: SchemaFormat,
): (name: string, typeDef: TypeDef) => SchemaTypeDefinition
function createTypeDefConverter(
  input: SchemaSummary,
  format: 'manifest',
): (name: string, typeDef: TypeDef) => ManifestTypeDefinition
function createTypeDefConverter(
  input: SchemaSummary,
  format: DefinitionFormat,
): (name: string, typeDef: TypeDef) => ConvertedTypeDefinition {
  const convertField = mapperWithHoisting(input.hoisted, (field) =>
    mutableSqueeze({
      group: field.groups,
      fieldset: field.fieldset,
      ...convertTypeDef(field.name, field.typeDef),
    }),
  )

  const convertArrayElement = mapperWithHoisting(input.hoisted, (element) =>
    convertTypeDef(element.name, element.typeDef),
  )

  /** Types whose raw `fields` array is always stripped (internal to Sanity). */
  const stripFieldsTypes = new Set([
    'block',
    'reference',
    'globalDocumentReference',
    'crossDatasetReference',
  ])

  /**
   * Built-in fields that Sanity adds automatically to image/file types. These
   * must be filtered out of any compiled output: Sanity re-injects them when the
   * schema is compiled, so leaving them in produces duplicate fields — notably the
   * Media Library `media` globalDocumentReference, which otherwise round-trips back
   * in and fails duplicate-field validation on the next compile. Custom
   * user-defined fields (e.g. `alt`) are preserved.
   */
  const builtInImageFields = new Set(['asset', 'hotspot', 'crop', 'media'])
  const builtInFileFields = new Set(['asset', 'media'])

  function filterBuiltInFields(
    typeFields: InlineOrHoisted[],
    builtIn: Set<string>,
  ): InlineOrHoisted[] {
    return typeFields.filter((f) => {
      if (isHoistedMarker(f)) return true
      return !builtIn.has(f.name)
    })
  }

  function findField(
    fields: InlineOrHoisted[] | undefined,
    name: string,
  ): HoistedEntry | undefined {
    for (const field of fields ?? []) {
      if (!isHoistedMarker(field)) {
        if (field.name === name) return field
        continue
      }

      const hoisted = input.hoisted[field.key]
      if (!hoisted) throw new Error(`Unknown hoisted key: ${field.key}`)
      if (hoisted.name === name) return hoisted
    }

    return undefined
  }

  function extractOptionList(field: HoistedEntry | undefined): unknown[] | undefined {
    const options = field?.typeDef['options']
    if (options === null || typeof options !== 'object') return undefined

    const list = (options as Record<string, unknown>)['list']
    if (!Array.isArray(list)) return undefined

    const decoded = decodeWithMarkers(list)
    if (!Array.isArray(decoded)) return undefined
    if (format === 'plain') return decoded

    return decoded.map((item) => {
      if (item === null || typeof item !== 'object' || Array.isArray(item)) return item
      const {title, value} = item as Record<string, unknown>
      return mutableSqueeze({title, value})
    })
  }

  function convertTypeDef(name: string, typeDef: TypeDef): ManifestTypeDefinition {
    const {extends: type, fields, fieldsets, to, of, validation, marks: rawMarks, ...rest} = typeDef
    const isCompiled = format !== 'plain'

    // Reconstruct a block's Portable Text options before its internal `fields`
    // are stripped below. Annotations come from `markDefs`, styles and lists from
    // their fields' option lists, and decorators from `block.marks.decorators`.
    // `createSchema` consumes these as top-level block properties.
    // `rawMarks` is pulled out of `...rest` so the raw producer shape can't flow
    // through `...decodeWithMarkers(rest)` below and clobber this reconstruction.
    let marks: {decorators?: unknown[]; annotations?: ConvertedTypeDefinition[]} | undefined
    let styles: unknown[] | undefined
    let lists: unknown[] | undefined
    if (type === 'block') {
      let annotations: ConvertedTypeDefinition[] | undefined
      const markDefsOf = findField(fields, 'markDefs')?.typeDef.of
      if (markDefsOf && markDefsOf.length > 0) {
        annotations = markDefsOf.map(convertArrayElement)
      }

      const decorators = extractDecorators(rawMarks)

      if (annotations || decorators) {
        marks = mutableSqueeze({decorators, annotations})
      }

      styles = extractOptionList(findField(fields, 'style'))
      lists = extractOptionList(findField(fields, 'listItem'))
    }

    // Determine which fields to include:
    // - Types in stripFieldsTypes always have fields removed entirely
    // - image/file types have built-in fields (asset/hotspot/crop/media) filtered
    //   out of compiled output; Sanity re-injects them and rejects duplicates
    // - All other types keep their fields as-is
    let convertedFields: unknown[] | undefined
    if (!fields || stripFieldsTypes.has(type)) {
      convertedFields = undefined
    } else if (isCompiled && type === 'image') {
      const filtered = filterBuiltInFields(fields, builtInImageFields)
      convertedFields = filtered.length > 0 ? filtered.map(convertField) : undefined
    } else if (isCompiled && type === 'file') {
      const filtered = filterBuiltInFields(fields, builtInFileFields)
      convertedFields = filtered.length > 0 ? filtered.map(convertField) : undefined
    } else {
      convertedFields = fields.map(convertField)
    }

    return mutableSqueeze({
      name,
      type,
      fields: convertedFields,
      fieldsets: (fieldsets?.length || 0) > 0 ? fieldsets : undefined,
      of: of ? of.map(convertArrayElement) : undefined,
      to: to?.map(({name}) =>
        mutableSqueeze({
          type: name,
          preview:
            isCompiled &&
            ['globalDocumentReference', 'crossDatasetReference'].includes(typeDef.extends)
              ? {
                  select: {title: '_id'},
                }
              : undefined,
        }),
      ),

      marks,
      styles,
      lists,

      validation:
        format === 'plain'
          ? validation
          : format === 'manifest'
            ? convertDescriptorValidationToManifest(validation)
            : undefined,

      dataset: isCompiled && typeDef.extends === 'crossDatasetReference' ? 'example' : undefined,

      resourceType:
        isCompiled && typeDef.extends === 'globalDocumentReference' ? 'media-library' : undefined,

      resourceId: isCompiled && typeDef.extends === 'globalDocumentReference' ? '_' : undefined,

      ...decodeWithMarkers(rest),
    })
  }

  if (format === 'manifest') {
    return convertTypeDef
  }

  // Keep schema and manifest conversion shared: their descriptor traversal is
  // intentionally identical, and splitting it duplicates the core mapping.
  // The cast is limited to the schema overload boundary because the Sanity
  // SchemaTypeDefinition union cannot express dynamic descriptor aliases.
  return (name, typeDef) => convertTypeDef(name, typeDef) as SchemaTypeDefinition
}

/**
 * Modifies the object to remove any `undefined` values.
 * Returns itself.
 */
function mutableSqueeze<T extends Record<string, unknown>>(obj: T): T {
  for (const [key, value] of Object.entries(obj)) {
    if (value === undefined) delete obj[key]
  }
  return obj
}

/**
 * Reads a block's decorators off the producer's `marks.decorators` shape. The
 * producer serializes them with the generic value encoder (keeping extras like
 * `i18nTitleKey` and encoding a non-serializable `icon` as a marker), so we decode
 * them with the same `decodeWithMarkers` used for every other pass-through value.
 *
 * An empty array is preserved (not collapsed to `undefined`): `marks.decorators: []`
 * means the block disables all decorators, which is distinct from a block that omits
 * `marks` and should fall back to the defaults. Dropping it would re-enable them.
 */
function extractDecorators(rawMarks: unknown): unknown[] | undefined {
  if (rawMarks === null || typeof rawMarks !== 'object') return undefined
  const decorators = (rawMarks as Record<string, unknown>)['decorators']
  if (!Array.isArray(decorators)) return undefined
  const decoded = decodeWithMarkers(decorators)
  return Array.isArray(decoded) ? decoded : undefined
}

function isHoistedMarker(x: unknown): x is HoistedMarker {
  if (x === null || typeof x !== 'object') return false
  const obj = x as Record<string, unknown>
  return obj['__type'] === 'hoisted' && typeof obj['key'] === 'string'
}

/**
 * Helper function for resolving hoisted values.
 */
function mapperWithHoisting<U extends object>(
  hoisted: Record<string, HoistedEntry>,
  map: (input: HoistedEntry) => U,
): (input: InlineOrHoisted) => U {
  const cache = new Map<string, U>()
  return (entry: InlineOrHoisted): U => {
    if (isHoistedMarker(entry)) {
      const cached = cache.get(entry.key)
      if (cached) return cached

      const value = hoisted[entry.key]
      if (!value) throw new Error(`Unknown hoisted key: ${entry.key}`)

      // Pre-populate the cache with a placeholder so a hoisted entry that
      // recursively references its own key resolves to the same object instead
      // of recursing forever. The placeholder is mutated in place once map()
      // returns, so any nested re-entrant lookup ends up sharing the
      // eventually-populated result.
      const placeholder = {} as U
      cache.set(entry.key, placeholder)
      Object.assign(placeholder, map(value))
      return placeholder
    }

    return map(entry)
  }
}

const STOP = Symbol('STOP')

function decodeWithMarkers<T>(x: T): T | undefined {
  const result = decodeWithMarkersOrStop(x)
  if (result === STOP) return undefined
  return result as T
}

function decodeWithMarkersOrStop(x: unknown): unknown | typeof STOP {
  if (x === null || x === undefined || typeof x !== 'object') return x

  if (Array.isArray(x)) {
    const result: unknown[] = []
    for (const item of x) {
      const decoded = decodeWithMarkersOrStop(item)
      if (decoded === STOP) return STOP
      result.push(decoded)
    }

    return result
  }

  if ('__type' in x) {
    const record = x as Record<string, unknown>
    switch (record['__type']) {
      case 'function':
      case 'jsx':
      case 'unknown':
      case 'cyclic':
      case 'maxDepth':
        return STOP
      case 'number':
        return Number(record['value'])
      case 'undefined':
        return undefined
      case 'object':
        return decodeWithMarkersOrStop(record['value'])
      default: {
        throw new Error(`unknown type: ${record['__type']}`)
      }
    }
  }

  const result: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(x)) {
    const decoded = decodeWithMarkers(value)
    result[key] = decoded
  }
  return result
}
