import type {ManifestSchemaType} from '@sanity/schema/_internal'

type ManifestValidationGroup = NonNullable<ManifestSchemaType['validation']>[number]
type ManifestValidationRule = ManifestValidationGroup['rules'][number]
type ManifestSerializable = NonNullable<ManifestValidationRule['constraint']>

type DescriptorValidationLevel = 'error' | 'warning' | 'info'

type DescriptorValidationMessage = string | Record<string, string>

// Local copy of the validation descriptor shapes from sanity-io/sanity:
// packages/@sanity/schema/src/descriptors/types.ts.
type DescriptorFieldReference = {
  type: 'fieldReference'
  path: string[]
}

type DescriptorNestedRule = {
  rules: DescriptorRule[]
  message?: DescriptorValidationMessage
}

type DescriptorRule =
  | {type: 'required'}
  | {type: 'integer'}
  | {type: 'email'}
  | {type: 'datetime'}
  | {type: 'uppercase'}
  | {type: 'lowercase'}
  | {type: 'uniqueItems'}
  | {type: 'reference'}
  | {type: 'assetRequired'}
  | {type: 'allOf'; children: DescriptorNestedRule[]}
  | {type: 'anyOf'; children: DescriptorNestedRule[]}
  | {type: 'enum'; values: unknown[]}
  | {type: 'minimum'; value: string | DescriptorFieldReference}
  | {type: 'exclusiveMinimum'; value: string | DescriptorFieldReference}
  | {type: 'maximum'; value: string | DescriptorFieldReference}
  | {type: 'exclusiveMaximum'; value: string | DescriptorFieldReference}
  | {type: 'length'; value: string | DescriptorFieldReference}
  | {type: 'precision'; value: string | DescriptorFieldReference}
  | {type: 'regex'; pattern: string; invert?: true}
  | {
      type: 'uri'
      scheme?: (string | {type: 'regex'; pattern: string})[]
      allowRelative?: boolean
      relativeOnly?: boolean
      allowCredentials?: boolean
    }
  | {type: 'custom'; name?: string; optional?: true}

type DescriptorValidation = {
  rules: unknown[]
  level: DescriptorValidationLevel
  message?: DescriptorValidationMessage
}

export function convertDescriptorValidationToManifest(
  validation: unknown,
): ManifestValidationGroup[] | undefined {
  if (!Array.isArray(validation)) return undefined

  const groups = validation
    .map((group) => convertDescriptorValidationGroup(group))
    .filter(isDefined)

  return groups.length > 0 ? groups : undefined
}

function convertDescriptorValidationGroup(group: unknown): ManifestValidationGroup | undefined {
  if (!isDescriptorValidation(group)) return undefined

  const rules = group.rules.map((rule) => convertDescriptorRule(rule)).filter(isDefined)
  if (rules.length === 0) return undefined

  return {
    rules,
    level: group.level,
    ...(typeof group.message === 'string' ? {message: group.message} : {}),
  }
}

// eslint-disable-next-line complexity
function convertDescriptorRule(rule: unknown): ManifestValidationRule | undefined {
  if (!isDescriptorRule(rule)) return undefined

  switch (rule.type) {
    case 'required':
      return {flag: 'presence', constraint: 'required'}
    case 'integer':
      return {flag: 'integer'}
    case 'email':
      return {flag: 'email'}
    case 'uppercase':
      return {flag: 'stringCasing', constraint: 'uppercase'}
    case 'lowercase':
      return {flag: 'stringCasing', constraint: 'lowercase'}
    case 'uniqueItems':
      return {flag: 'unique'}
    case 'reference':
      return {flag: 'reference'}
    case 'assetRequired':
      return {flag: 'assetRequired'}
    case 'allOf':
    case 'anyOf':
      // createSchemaFromManifestTypes currently compiles composed manifest rules
      // into callbacks, while Studio validation expects nested Rule instances.
      return undefined
    case 'enum':
      return convertEnumRule(rule.values)
    case 'minimum':
      return convertStringConstraintRule('min', rule.value)
    case 'maximum':
      return convertStringConstraintRule('max', rule.value)
    case 'exclusiveMinimum':
      return convertNumberConstraintRule('greaterThan', rule.value)
    case 'exclusiveMaximum':
      return convertNumberConstraintRule('lessThan', rule.value)
    case 'length':
      return convertNumberConstraintRule('length', rule.value)
    case 'precision':
      return convertNumberConstraintRule('precision', rule.value)
    case 'regex':
      return convertRegexRule(rule)
    case 'uri':
      return convertUriRule(rule)
    case 'custom':
      return {flag: rule.name === 'media' ? 'media' : 'custom'}
    case 'datetime':
      return undefined
    default: {
      const exhaustive: never = rule
      return exhaustive
    }
  }
}

function convertEnumRule(values: unknown): ManifestValidationRule | undefined {
  if (!Array.isArray(values)) return undefined

  const constraint = values.map((value) => toManifestSerializable(value)).filter(isDefined)
  return constraint.length > 0 ? {flag: 'valid', constraint} : undefined
}

function convertStringConstraintRule(
  flag: 'min' | 'max',
  value: unknown,
): ManifestValidationRule | undefined {
  // Keep min/max as strings so date and number constraints both survive the
  // manifest handoff; exclusive bounds, length and precision are numeric-only.
  return typeof value === 'string' ? {flag, constraint: value} : undefined
}

function convertNumberConstraintRule(
  flag: 'greaterThan' | 'lessThan' | 'length' | 'precision',
  value: unknown,
): ManifestValidationRule | undefined {
  if (typeof value !== 'string') return undefined

  const constraint = Number(value)
  return Number.isFinite(constraint) ? {flag, constraint} : undefined
}

function convertRegexRule(rule: Extract<DescriptorRule, {type: 'regex'}>): ManifestValidationRule {
  return {
    flag: 'regex',
    constraint: {
      pattern: rule.pattern,
      ...(rule.invert ? {invert: true} : {}),
    },
  }
}

function convertUriRule(rule: Extract<DescriptorRule, {type: 'uri'}>): ManifestValidationRule {
  const options: Record<string, ManifestSerializable> = {}
  if (rule.scheme !== undefined) options['scheme'] = rule.scheme
  if (rule.allowRelative !== undefined) options['allowRelative'] = rule.allowRelative
  if (rule.relativeOnly !== undefined) options['relativeOnly'] = rule.relativeOnly
  if (rule.allowCredentials !== undefined) options['allowCredentials'] = rule.allowCredentials

  return {
    flag: 'uri',
    constraint: {options},
  }
}

function toManifestSerializable(value: unknown): ManifestSerializable | undefined {
  const decoded = decodeDescriptorMarker(value)
  if (decoded === null || decoded === undefined) return undefined

  if (typeof decoded === 'string' || typeof decoded === 'number' || typeof decoded === 'boolean') {
    return decoded
  }

  if (Array.isArray(decoded)) {
    const items = decoded.map((item) => toManifestSerializable(item)).filter(isDefined)
    return items.length > 0 ? items : undefined
  }

  if (isRecord(decoded)) {
    const entries = Object.entries(decoded)
      .map(([key, nestedValue]) => [key, toManifestSerializable(nestedValue)] as const)
      .filter((entry): entry is readonly [string, ManifestSerializable] => entry[1] !== undefined)

    return entries.length > 0 ? Object.fromEntries(entries) : undefined
  }

  return undefined
}

function decodeDescriptorMarker(value: unknown): unknown {
  if (!isRecord(value) || !('__type' in value)) return value

  switch (value['__type']) {
    case 'number':
      return Number(value['value'])
    case 'undefined':
    case 'function':
    case 'jsx':
    case 'unknown':
    case 'cyclic':
    case 'maxDepth':
      return undefined
    case 'object':
      return decodeDescriptorMarker(value['value'])
    default:
      return value
  }
}

function isDescriptorValidation(value: unknown): value is DescriptorValidation {
  return (
    isRecord(value) &&
    Array.isArray(value['rules']) &&
    isValidationLevel(value['level']) &&
    (!('message' in value) || typeof value['message'] === 'string' || isRecord(value['message']))
  )
}

function isValidationLevel(value: unknown): value is DescriptorValidationLevel {
  return value === 'error' || value === 'warning' || value === 'info'
}

function isDescriptorRule(value: unknown): value is DescriptorRule {
  if (!isRecord(value) || typeof value['type'] !== 'string') return false

  switch (value['type']) {
    case 'required':
    case 'integer':
    case 'email':
    case 'datetime':
    case 'uppercase':
    case 'lowercase':
    case 'uniqueItems':
    case 'reference':
    case 'assetRequired':
    case 'custom':
      return true
    case 'allOf':
    case 'anyOf':
      return Array.isArray(value['children'])
    case 'enum':
      return Array.isArray(value['values'])
    case 'minimum':
    case 'exclusiveMinimum':
    case 'maximum':
    case 'exclusiveMaximum':
    case 'length':
    case 'precision':
      return typeof value['value'] === 'string' || isFieldReference(value['value'])
    case 'regex':
      return typeof value['pattern'] === 'string'
    case 'uri':
      return true
    default:
      return false
  }
}

function isFieldReference(value: unknown): value is DescriptorFieldReference {
  return isRecord(value) && value['type'] === 'fieldReference' && Array.isArray(value['path'])
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
}

function isDefined<T>(value: T | undefined): value is T {
  return value !== undefined
}
